/* Mbed TLS configuration for THE WRLD OS: a TLS client only (The WRLD Xplorer,
 * wget/curl), TLS 1.3 and 1.2, built freestanding inside the kernel. */
#ifndef WRLD_MBEDTLS_CONFIG_H
#define WRLD_MBEDTLS_CONFIG_H
#define MBEDTLS_CONFIG_VERSION 0x04000000

/* TLS */
#define MBEDTLS_SSL_TLS_C
#define MBEDTLS_SSL_CLI_C
#define MBEDTLS_SSL_PROTO_TLS1_2
#define MBEDTLS_SSL_PROTO_TLS1_3
#define MBEDTLS_SSL_TLS1_3_COMPATIBILITY_MODE
#define MBEDTLS_SSL_TLS1_3_KEY_EXCHANGE_MODE_EPHEMERAL_ENABLED
#define MBEDTLS_KEY_EXCHANGE_ECDHE_ECDSA_ENABLED
#define MBEDTLS_KEY_EXCHANGE_ECDHE_RSA_ENABLED
#define MBEDTLS_SSL_SERVER_NAME_INDICATION
#define MBEDTLS_SSL_ALPN
#define MBEDTLS_SSL_EXTENDED_MASTER_SECRET
#define MBEDTLS_SSL_ENCRYPT_THEN_MAC
#define MBEDTLS_SSL_ALL_ALERT_MESSAGES
#define MBEDTLS_SSL_KEEP_PEER_CERTIFICATE      /* required by TLS 1.3 */
#define MBEDTLS_SSL_SESSION_TICKETS            /* so TLS 1.3 NewSessionTicket messages are understood */
#define MBEDTLS_SSL_IN_CONTENT_LEN  16384
#define MBEDTLS_SSL_OUT_CONTENT_LEN 16384

/* certificates */
#define MBEDTLS_X509_USE_C
#define MBEDTLS_X509_CRT_PARSE_C
#define MBEDTLS_X509_RSASSA_PSS_SUPPORT
#define MBEDTLS_X509_TRUSTED_CERTIFICATE_CALLBACK   /* roots are parsed on demand, by issuer name */
#define MBEDTLS_X509_MAX_INTERMEDIATE_CA 8

/* error texts for messages the browser shows */
#define MBEDTLS_ERROR_C
#define MBEDTLS_VERSION_C
#endif
